7	export default function isObject(thing: any): thing is object {
8	  if (typeof thing !== 'object' || thing === null) {
9	    return false;
10	  }
11	  // lastModified is guaranteed to be a number on a File instance
12	  // as per https://w3c.github.io/FileAPI/#dfn-lastModified
13	  if (typeof thing.lastModified === 'number' && typeof File !== 'undefined' && thing instanceof File) {
