10	/** Returns the unique list of schema types for all of the options in a anyOf/oneOf
11	 *
12	 * @param schemas - The list of schemas representing the XxxOf options
13	 * @returns - All of the unique types contained within the oneOf list
14	 */
15	export function getSchemaTypesForXxxOf<S extends StrictRJSFSchema = RJSFSchema>(schemas: S[]): string | string[] {
16	  const allTypes: string[] = uniq(
17	    schemas
18	      .map((s) => (isObject(s) ? getSchemaType(s) : undefined))
19	      .flat()
20	      .filter((t) => t !== undefined),
21	  );
22	  return allTypes.length === 1 ? allTypes[0] : allTypes;
23	}
