25	/** Determines whether the field information from the combination of `schema` and `required` along with the
26	 * `enableOptionalDataFieldForType` settings from the global UI options in the `registry` all indicate that this field
27	 * should be rendered with the Optional Data Controls UI.
28	 *
29	 * @param registry - The `registry` object
30	 * @param schema - The schema for the field
31	 * @param required - Flag indicating whether the field is required
32	 * @param [uiSchema] - The uiSchema for the field
33	 * @return - True if the field should be rendered with the optional field UI, otherwise false
34	 */
35	export default function shouldRenderOptionalField<
36	  T = any,
37	  S extends StrictRJSFSchema = RJSFSchema,
38	  F extends FormContextType = any,
39	>(registry: Registry<T, S, F>, schema: S, required: boolean, uiSchema?: UiSchema<T, S, F>): boolean {
40	  const { enableOptionalDataFieldForType = [] } = getUiOptions<T, S, F>(uiSchema, registry.globalUiOptions);
41	  let schemaType: ReturnType<typeof getSchemaType<S>>;
42	  if (ANY_OF_KEY in schema && Array.isArray(schema[ANY_OF_KEY])) {
43	    schemaType = getSchemaTypesForXxxOf<S>(schema[ANY_OF_KEY] as S[]);
44	  } else if (ONE_OF_KEY in schema && Array.isArray(schema[ONE_OF_KEY])) {
45	    schemaType = getSchemaTypesForXxxOf<S>(schema[ONE_OF_KEY] as S[]);
46	  } else {
47	    schemaType = getSchemaType<S>(schema);
48	  }
49	  return (
50	    !isRootSchema<T, S, F>(registry, schema) &&
51	    !required &&
52	    !!schemaType &&
53	    !Array.isArray(schemaType) &&
54	    !!enableOptionalDataFieldForType.find((val) => val === schemaType)
55	  );
56	}
