import { ITEMS_KEY, PROPERTIES_KEY, REQUIRED_KEY } from './constants';
import { FormContextType, RJSFSchema, StrictRJSFSchema, ValidatorType } from './types';

const ADDITIONAL_ITEMS_KEY = 'additionalItems';

/** Determines whether a `value`, that has already been recursively processed, is considered "empty" for the purposes of
 * pruning optional properties. A value is empty when it is `undefined`, `null`, an empty string, or an empty array.
 * Note that boolean `false` and the number `0` are NOT considered empty. Objects that were fully pruned during the
 * recursive processing will have been reduced to `undefined`, so they are caught by the `undefined` check.
 *
 * @param value - The already processed value to check for emptiness
 * @returns - True when the `value` is considered empty, otherwise false
 */
function isEmptyValue(value: any): boolean {
  if (value === undefined || value === null || value === '') {
    return true;
  }
  if (Array.isArray(value) && value.length === 0) {
    return true;
  }
  return false;
}

/** Recursively traverses `formData` against the given `schema` and removes any optional properties (object, scalar, or
 * array) whose values are considered "empty" (`undefined`, `null`, an empty string, an empty array, or a nested object
 * that is itself fully empty after processing). Required properties (those listed in the schema's `required` array) are
 * NOT removed — if a required property's value is processed to empty, its key is retained but set to `undefined`.
 * Properties present in `formData` but not defined in the `schema` are preserved as-is. When all properties of an object
 * are pruned, the function returns `undefined` instead of an empty object. Arrays are processed item-by-item using the
 * appropriate per-item schema (tuple items by index, `additionalItems` for out-of-bounds indices, or as-is when no
 * schema applies). Boolean `false` and the number `0` are NOT considered empty.
 *
 * @param validator - An implementation of the `ValidatorType` interface that is used when resolving schema conditions
 * @param schema - The schema against which the `formData` is being processed
 * @param rootSchema - The root schema, used when resolving references within nested schemas
 * @param formData - The form data being processed and pruned of empty optional values
 * @returns - The processed `formData` with empty optional values removed, or `undefined` when nothing meaningful remains
 */
export default function removeOptionalEmptyObjects<
  T = any,
  S extends StrictRJSFSchema = RJSFSchema,
  F extends FormContextType = any,
>(validator: ValidatorType<T, S, F>, schema: S, rootSchema: S, formData: any): any | undefined {
  // When there is no form data there is nothing to process.
  if (formData === undefined) {
    return undefined;
  }

  // Scalars (and any other non-object, non-array values) are returned unchanged; their emptiness is evaluated by the
  // parent that owns them.
  if (!isObject(formData) && !Array.isArray(formData)) {
    return formData;
  }

  // Without a schema there is nothing to compare the form data against, so return it unchanged.
  if (!schema) {
    return formData;
  }

  // Arrays are processed item-by-item using the appropriate per-item schema.
  if (Array.isArray(formData)) {
    const items = (schema as RJSFSchema)[ITEMS_KEY];
    if (items === undefined) {
      return formData;
    }
    const additionalItems = (schema as RJSFSchema)[ADDITIONAL_ITEMS_KEY];
    let changed = false;
    const processedItems = formData.map((item, index) => {
      let itemSchema: any;
      if (Array.isArray(items)) {
        // Tuple schema: use the schema at the matching index, falling back to `additionalItems` for out-of-bounds
        // indices when it is defined.
        itemSchema = index < items.length ? items[index] : additionalItems;
      } else {
