        itemSchema = items;
      }
      // When no schema applies to an element, leave it unchanged.
      if (itemSchema === undefined || itemSchema === null) {
        return item;
      }
      const processed = removeOptionalEmptyObjects<T, S, F>(validator, itemSchema as S, rootSchema, item);
      if (!deepEquals(processed, item)) {
        changed = true;
      }
      return processed;
