    ? ((schema as RJSFSchema)[REQUIRED_KEY] as string[])
    : [];
  // Start from a shallow copy so that properties not defined in the schema are preserved as-is.
  const result: { [key: string]: any } = { ...formData };

  Object.keys(properties).forEach((key) => {
    if (!(key in formData)) {
      return;
    }
    const propertySchema = properties[key];
    const processed = removeOptionalEmptyObjects<T, S, F>(validator, propertySchema as S, rootSchema, formData[key]);
