as S, rootSchema, formData[key]);\n    if (isEmptyValue(processed)) {\n      if (required.includes(key)) {\n        // Required properties are retained but reset to `undefined` when empty.\n        result[key] = undefined;\n      } else {\n        // Optional empty properties are removed entirely.\n        delete result[key];\n      }\n    } else {\n      result[key] = processed;\n    }\n  });\n\n  // When everything has been pruned (deleted or reset to `undefined`) there is no meaningful data left, so collapse the\n  // object to `undefined`.\n  const hasMeaningfulData = Object.keys(result).some((key) => result[key] !== undefined);\n  if (!hasMeaningfulData) {\n    return undefined;\n  }\n\n  return result;\n}\n"],"mappings":";;;;;;AAAA,IAAAA,SAAA,GAAAC,sBAAA,CAAAC,OAAA;AACA,IAAAC,WAAA,GAAAF,sBAAA,CAAAC,OAAA;AACA,IAAAE,UAAA,GAAAF,OAAA;AAAsE,SAAAD,uBAAAI,CAAA,WAAAA,CAAA,IAAAA,CAAA,CAAAC,UAAA,GAAAD,CAAA,KAAAE,OAAA,EAAAF,CAAA;AAGtE,MAAMG,oBAAoB,GAAG,iBAAiB;;AAE9C;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,SAASC,YAAYA,CAACC,KAAU,EAAW;EACzC,IAAIA,KAAK,KAAKC,SAAS,IAAID,KAAK,KAAK,IAAI,IAAIA,KAAK,KAAK,EAAE,EAAE;IACzD,OAAO,IAAI;EACb;EACA,IAAIE,KAAK,CAACC,OAAO,CAACH,KAAK,CAAC,IAAIA,KAAK,CAACI,MAAM,KAAK,CAAC,EAAE;IAC9C,OAAO,IAAI;EACb;EACA,OAAO,KAAK;AACd;;AAEA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACe,SAASC,0BAA0BA,CAIhDC,SAAiC,EAAEC,MAAS,EAAEC,UAAa,EAAEC,QAAa,EAAmB;EAC7F;EACA,IAAIA,QAAQ,KAAKR,SAAS,EAAE;IAC1B,OAAOA,SAAS;EAClB;;EAEA;EACA;EACA,IAAI,CAAC,IAAAS,iBAAQ,EAACD,QAAQ,CAAC,IAAI,CAACP,KAAK,CAACC,OAAO,CAACM,QAAQ,CAAC,EAAE;IACnD,OAAOA,QAAQ;EACjB;;EAEA;EACA,IAAI,CAACF,MAAM,EAAE;IACX,OAAOE,QAAQ;EACjB;;EAEA;EACA,IAAIP,KAAK,CAACC,OAAO,CAACM,QAAQ,CAAC,EAAE;IAC3B,MAAME,KAAK,GAAIJ,MAAM,CAAgBK,oBAAS,CAAC;IAC/C,IAAID,KAAK,KAAKV,SAAS,EAAE;MACvB,OAAOQ,QAAQ;IACjB;IACA,MAAMI,eAAe,GAAIN,MAAM,CAAgBT,oBAAoB,CAAC;IACpE,IAAIgB,OAAO,GAAG,KAAK;IACnB,MAAMC,cAAc,GAAGN,QAAQ,CAACO,GAAG,CAAC,CAACC,IAAI,EAAEC,KAAK,KAAK;MACnD,IAAIC,UAAe;MACnB,IAAIjB,KAAK,CAACC,OAAO,CAACQ