+import removeOptionalEmptyObjects from './packages/utils/src/removeOptionalEmptyObjects';
+const v: any = {};
+const r = (s: any, d: any) => removeOptionalEmptyObjects(v, s, s, d);
+test('undefined formData', () => expect(r({}, undefined)).toBeUndefined());
+test('scalar unchanged', () => expect(r({}, 'hi')).toBe('hi'));
+test('null schema', () => expect(r(null, { a: 1 })).toEqual({ a: 1 }));
+test('no properties', () => expect(r({ type: 'object' }, { a: '' })).toEqual({ a: '' }));
+test('remove optional empty string', () =>
+  expect(r({ properties: { a: {}, b: {} } }, { a: '', b: 'x' })).toEqual({ b: 'x' }));
+test('required kept undefined', () =>
+  expect(r({ properties: { a: {}, b: {} }, required: ['a'] }, { a: '', b: 'x' })).toEqual({ a: undefined, b: 'x' }));
+test('false/0 not empty', () =>
+  expect(r({ properties: { a: {}, b: {} } }, { a: false, b: 0 })).toEqual({ a: false, b: 0 }));
+test('unknown prop preserved', () =>
+  expect(r({ properties: { a: {} } }, { a: 'x', z: 'keep' })).toEqual({ a: 'x', z: 'keep' }));
+test('all pruned -> undefined', () =>
+  expect(r({ properties: { a: {}, b: {} } }, { a: '', b: null })).toBeUndefined());
+test('nested empty object collapses', () =>
+  expect(
+    r({ properties: { outer: { properties: { inner: {} } } } }, { outer: { inner: '' } })
+  ).toBeUndefined());
+test('array single items', () =>
+  expect(
+    r({ type: 'array', items: { properties: { a: {} } } }, [{ a: '' }, { a: 'x' }])
+  ).toEqual([undefined, { a: 'x' }]));
+test('array no items as-is', () => {
+  const arr = [1, 2];
+  expect(r({ type: 'array' }, arr)).toBe(arr);
+});
+test('array no change as-is', () => {
+  const arr = [{ a: 'x' }];
+  expect(r({ type: 'array', items: { properties: { a: {} } } }, arr)).toBe(arr);
+});
+test('tuple items with additionalItems', () =>
+  expect(
+    r({ type: 'array', items: [{ properties: { a: {} } }], additionalItems: { properties: { b: {} } } },
+      [{ a: '' }, { b: 'y' }])
+  ).toEqual([undefined, { b: 'y' }]));
